from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
script=defs+'''
let attached=true,narrow=false;function rebuild(){const f=document.getElementById('fixture');f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());f.style.width=(narrow?480:906)+'px';f.style.display=attached?'block':'none';f.querySelectorAll('thead th').forEach((x,i)=>x.id='CapabilityHeader-cell-'+i)}rebuild();
function snapshot(){const row=document.querySelector('thead tr'),b=row.getBoundingClientRect();return{english:lang==='en',attached,narrow,focused:document.activeElement?.id??'',width:b.width,height:b.height,texts:[...row.cells].map(c=>c.textContent),background:getComputedStyle(row.cells[0]).backgroundColor}}
async function record(){const res=await fetch('/evidence/preflight-capabilityheader-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot())});if(!res.ok)throw Error('Record failed');document.getElementById('capabilityheader-input-record').textContent='Header input recorded'}
let headerRecordTimer;function later(){clearTimeout(headerRecordTimer);headerRecordTimer=setTimeout(record,40)}
document.getElementById('capabilityheader-input-record').addEventListener('mousedown',e=>e.preventDefault());document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.id==='CapabilityHeader-language'){lang=lang==='ko'?'en':'ko';rebuild()}if(b?.id==='CapabilityHeader-width'){narrow=!narrow;rebuild()}if(b?.id==='CapabilityHeader-mount'){attached=!attached;rebuild()}if(b?.id==='capabilityheader-input-record')record();else later()});
'''
(o/'capabilityheader-input.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityHeader Input · original isolation</title><link rel="stylesheet" href="capabilityheader-original.css"><style>#fixture{position:absolute;left:30px;top:60px}</style><div id="fixture"></div><button id="CapabilityHeader-language">language</button><button id="CapabilityHeader-width">width</button><button id="CapabilityHeader-mount">mount</button><button id="capabilityheader-input-record">Record Header Input</button><script>'+script+'</script>');print('Original header input fixture prepared')
